H.background();
const v = H.plot2d({ xMin: -1, xMax: 19, yMin: -1, yMax: 9 });
v.grid(); v.axes();
const spd = Math.max(1, P.speed), deg = P.angle, g = Math.max(1, P.g);
const ang = deg * Math.PI / 180;
const vx = spd * Math.cos(ang), vy = spd * Math.sin(ang);
// projectile: x(tau) = vx*tau, y(tau) = vy*tau - 0.5 g tau^2
const tflight = Math.max(0.1, 2 * vy / g);
const X = (tau) => vx * tau;
const Y = (tau) => vy * tau - 0.5 * g * tau * tau;
const pts = [];
for (let i = 0; i <= 120; i++) { const tau = tflight * i / 120; pts.push([X(tau), Math.max(0, Y(tau))]); }
v.path(pts, { color: H.colors.accent, width: 2.5 });
// the ball flies, then the flight loops
const tau = (t * 1.2) % tflight;
const bx = X(tau), by = Math.max(0, Y(tau));
v.arrow(bx, by, bx + vx * 0.25, by + (vy - g * tau) * 0.25, { color: H.colors.violet, width: 2 });
v.dot(bx, by, { r: 7, fill: H.colors.warn });
const range = vx * tflight;
v.dot(range, 0, { r: 5, fill: H.colors.good });
H.text("Parametric motion: position over time", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("x = v*cos(theta)*t,  y = v*sin(theta)*t - 0.5 g t^2", 24, 52, { color: H.colors.sub, size: 12 });
H.text("t = " + tau.toFixed(2) + "s   x = " + bx.toFixed(1) + "   y = " + by.toFixed(1) + "   range = " + range.toFixed(1), 24, 72, { color: H.colors.good, size: 13 });
